INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, test_String) SELECT @e, 63, 8, 1.0, 0, 'Go gently, %s. The winds are with you.', 'AzimarLines:bless' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, test_String) SELECT @e, 0, 8, 0, 0, 'The winds are kind today.', 'AzimarLines:idle' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'A new face on the wind! Welcome, %s. I am Azimar, and you are very welcome here.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Ah, %s. The winds whispered that someone new was coming. Come closer.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Well met, %s. Every journey starts small. Let us make yours a little brighter.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Hello, little traveler. %s, is it? A fine name to carry into the world.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'First time on my breeze, %s? Do not be shy. I only bite rumours.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'Welcome to the kinder winds of Dereth, %s. Stand still and I will lend you some.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, '%s! I do not know you yet, but the sky tells me I will.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'Come in, come in, %s. A Zefir never forgets a new friend.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Back again, %s? Good. The winds missed you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s! I hoped you would come by.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'There you are, %s. Ready for another lift?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Ah, my friend %s. Let us see what the winds have saved for you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Welcome back, %s. Your wings have not grown in yet, but we will get there.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, '%s returns! The breeze always brightens when you do.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, '%s! It has been days. I was starting to think the wind had carried you off.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Well, look who the storm blew back. Welcome home, %s.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, '%s, where have you been? Never mind. Tell the winds later.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Long roads, %s? I can see the dust on you. Rest a moment.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Your %visit visit, %s! At this rate I will have to name a breeze after you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s again! This is your %visit blessing. The winds save you a seat now.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Ah, %s, my most faithful guest. Your %visit visit, by my count, and I always count.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, '%s, I could set the sun by you. The %visit time you have flown in!' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Still green as spring leaves, %s. That is the best time to be blessed.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Small steps, %s. Even the high winds start as a whisper.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Mind the drudges out there, %s. They are rude and they bite.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'You have grown, %s. I can feel it in how the air moves around you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'No longer a fledgling, %s. Your feathers are coming in nicely.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Halfway up the mountain, %s. The view only gets better.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, '%s, the seasoned wanderer. Even you could use a fresh wind.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'I have heard your name on far breezes, %s. The tales are kind.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'A veteran of many roads. Welcome, %s. Rest those weary bones.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, '%s! A legend stands before me. I should be asking for your blessing.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'The high winds bow to you, %s. Still, a little extra never hurts.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Few climb as high as you have, %s. Let me polish that shine.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Good morning, %s. The dawn wind is the freshest of all.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Up with the sun, %s? So are the best adventurers.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Morning, %s. I have been riding the sunrise. Want some?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Good day, %s. The sky is wide open today.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'A fine bright afternoon, %s. Perfect for flying, or for walking very fast.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Hello, %s. The midday winds are warm and generous.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Good evening, %s. The dusk breeze carries the day''s stories.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'The sun is going down, %s. Best to be blessed before the dark.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Evening, %s. The sky is turning gold, like me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Out late, %s? The night winds keep secrets. I will keep yours.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Even the stars are awake for you, %s. Come, quickly.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'A night traveler! Brave of you, %s. Let me lend you a little light.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, '%n spreads his shimmering wings. "Hold still now. This tickles."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%n spreads his wings wide and the air turns warm. "Breathe in."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, '%n spreads his golden wings. "Let the bright winds find you."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, '%n spreads his wings and hums an old sky song.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, '%n spreads his wings, scattering motes of light. "Here they come."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, '%n spreads his shimmering wings. "One gift for every wind I know."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'There. The winds are with you now, %s. Go gently.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Fly well, %s, even if you must do it on foot.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Go on, %s. The road is brighter than it was a moment ago.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'May your path be short and your packs be heavy, %s.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Blessed and ready. Come back when the glow fades, %s.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'The sky keeps watch over you, %s. So do I.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, 'Off you go, %s. Bring me a good story next time.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'Safe winds, %s. Do not let the monsters see you coming.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Your first blessing, %s. Come back whenever it fades. I am always here.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Remember my name, %s: Azimar. The winds will bring you back to me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'That glow lasts a while, %s. When it fades, you know where to find me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Patience, %s. My winds are still gathering. Come back in %tqt.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Not yet, little one. Give the breeze %tqt to catch its breath.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'So eager! I like that. Try again in %tqt.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'My wings need %tqt more, %s. Even a Zefir gets tired.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'The winds are restless today. Something good is coming.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Psst, %s. Yes, you. You look like you could use a blessing.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Have you ever seen Dereth from above the clouds? It is mostly rooftops.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Hmm, hmm, hmm. Do not mind me. Just humming to the breeze.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Free blessings! Bright winds! No refunds on the glow.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, '%s, you have the look of someone about to do something brave.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, 'My kin ride the storms beyond the mountains. I prefer the company down here.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'If anyone needs a lift for the road, you know where I hover.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Ahh, the morning breeze. Nothing like it.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Rise and shine, %s. The day wants adventurers.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'The stars are out. Even the wind speaks softly now.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Up late, %s? Same as me. Zefirs hardly sleep.' FROM DUAL WHERE @e IS NOT NULL;
